do $polygo_content$
declare
  d constant jsonb := $content${"lessons":[{"id":"a1-u01-context","unit_id":"a1-u01","position":11,"title_es":"En contexto: un primer encuentro","objective_es":"Entender un saludo escrito y una presentación oral.","intro":{"explanation":"Vas a leer un mensaje y a escuchar a dos personas que se conocen. No hace falta entender cada palabra: buscá quién habla, cuándo y qué quiere.","examples":[{"target":"Nice to meet you.","base":"Encantado de conocerte."},{"target":"Fine, thank you. And you?","base":"Bien, gracias. ¿Y vos?"}]},"takeaways":["Ahora podés entender quién saluda, cuándo y qué pregunta en un mensaje corto."]},{"id":"a1-u02-context","unit_id":"a1-u02","position":11,"title_es":"En contexto: ¿quién es quién?","objective_es":"Entender una ficha sobre personas y preguntas con «to be» dirigidas a vos.","intro":{"explanation":"Vas a leer una ficha sobre dos personas y a escuchar a una profesora que te hace preguntas. Fijate en quién es quién y en qué te preguntan a vos.","examples":[{"target":"He is not happy.","base":"Él no está contento."},{"target":"Are you a student?","base":"¿Sos estudiante?"}]},"takeaways":["Ahora podés entender quién es quién en un texto corto y qué te preguntan con «to be»."]},{"id":"a1-u03-context","unit_id":"a1-u03","position":11,"title_es":"En contexto: tarjetas de jugadores","objective_es":"Entender datos de jugadores: número, edad y país.","intro":{"explanation":"Vas a leer las tarjetas de tres jugadores de un equipo infantil y a escuchar a un entrenador hablar con un chico nuevo. Prestá atención a los números.","examples":[{"target":"I am from Mexico.","base":"Soy de México."},{"target":"He is twelve years old.","base":"Tiene doce años."}]},"takeaways":["Ahora podés encontrar y comparar números, edades y países en un texto corto."]},{"id":"a1-u04-context","unit_id":"a1-u04","position":11,"title_es":"En contexto: la familia de Ana","objective_es":"Entender una descripción y una conversación sobre una familia.","intro":{"explanation":"Vas a leer cómo describe Ana a su familia y a escuchar una conversación sobre una foto. Fijate en las relaciones: quién es hermano, abuela o bebé de quién.","examples":[{"target":"My sister has a baby.","base":"Mi hermana tiene un bebé."},{"target":"Who is he?","base":"¿Quién es él?"}]},"takeaways":["Ahora podés entender quién es quién en una familia descripta en inglés."]},{"id":"a1-u05-context","unit_id":"a1-u05","position":11,"title_es":"En contexto: ¿cuál es el tuyo?","objective_es":"Entender mensajes sobre objetos: de quién son, cómo son.","intro":{"explanation":"Vas a leer un mensaje y escuchar una conversación sobre cosas que alguien encontró. Fijate en el color, el tamaño y de quién es cada cosa.","examples":[{"target":"Is this your book?","base":"¿Este es tu libro?"},{"target":"That phone is black.","base":"Ese teléfono es negro."}]},"takeaways":["Ahora podés entender de quién es un objeto y cómo es, en un mensaje corto."]},{"id":"a1-u06-context","unit_id":"a1-u06","position":11,"title_es":"En contexto: un departamento en alquiler","objective_es":"Entender un aviso de alquiler y dónde está cada cosa.","intro":{"explanation":"Vas a leer un aviso de un departamento y a escuchar a la dueña mostrarlo. Buscá cuántas habitaciones hay y dónde está cada cosa.","examples":[{"target":"There are two bedrooms.","base":"Hay dos dormitorios."},{"target":"The keys are on the table.","base":"Las llaves están sobre la mesa."}]},"takeaways":["Ahora podés entender qué tiene una casa y dónde está cada cosa."]},{"id":"a1-u07-context","unit_id":"a1-u07","position":11,"title_es":"En contexto: en el café","objective_es":"Entender un menú y un pedido en un café.","intro":{"explanation":"Vas a leer el menú de un café y a escuchar a una clienta pedir. Fijate qué hay en cada comida del día y qué pide ella.","examples":[{"target":"I want eggs and bread, please.","base":"Quiero huevos y pan, por favor."},{"target":"Are you hungry?","base":"¿Tenés hambre?"}]},"takeaways":["Ahora podés entender un menú sencillo y un pedido en un café."]},{"id":"a1-u08-context","unit_id":"a1-u08","position":11,"title_es":"En contexto: la semana de Tom","objective_es":"Entender un mensaje escrito y uno de voz sobre rutinas.","intro":{"explanation":"Vas a leer un mensaje de Tom sobre su rutina y a escuchar un mensaje de voz que le deja a su mamá. Fijate qué hace siempre, qué no hace y dónde.","examples":[{"target":"I never watch TV.","base":"Nunca miro televisión."},{"target":"She doesn't work.","base":"Ella no trabaja."}]},"takeaways":["Ahora podés entender qué hace alguien todos los días y qué no hace nunca."]},{"id":"a1-u09-context","unit_id":"a1-u09","position":11,"title_es":"En contexto: el programa del museo","objective_es":"Entender un horario y un anuncio con días y horas.","intro":{"explanation":"Vas a leer el horario de un museo y a escuchar un anuncio. Buscá qué días abre, a qué hora y cuándo cierra.","examples":[{"target":"The museum opens at nine o'clock.","base":"El museo abre a las nueve."},{"target":"at half past ten","base":"a las diez y media"}]},"takeaways":["Ahora podés encontrar días y horarios en un programa y en un anuncio."]},{"id":"a1-u10-context","unit_id":"a1-u10","position":11,"title_es":"En contexto: ¿cómo llego?","objective_es":"Entender carteles e indicaciones para llegar a un lugar.","intro":{"explanation":"Vas a leer un cartel, escuchar a alguien que pide indicaciones en la calle y seguir unas indicaciones escritas. Fijate hacia dónde hay que ir y si queda cerca o lejos.","examples":[{"target":"Go straight on and turn left.","base":"Seguí derecho y doblá a la izquierda."},{"target":"The hotel is far.","base":"El hotel queda lejos."}]},"takeaways":["Ahora podés entender indicaciones sencillas para llegar a un lugar."]},{"id":"a1-u11-context","unit_id":"a1-u11","position":11,"title_es":"En contexto: una publicación sobre hobbies","objective_es":"Entender una publicación y una conversación sobre gustos.","intro":{"explanation":"Vas a leer lo que cuenta Lily sobre sus pasatiempos y a escuchar a dos amigos hablar de lo que les gusta. Fijate qué les encanta, qué odian y qué saben hacer.","examples":[{"target":"I can't play football.","base":"No sé jugar al fútbol."},{"target":"My favorite sport is swimming.","base":"Mi deporte favorito es la natación."}]},"takeaways":["Ahora podés entender qué le gusta a alguien, qué odia y qué sabe hacer."]},{"id":"a1-u12-context","unit_id":"a1-u12","position":11,"title_es":"En contexto: una conversación completa","objective_es":"Entender una conversación en clase y las preguntas que te hacen a vos.","intro":{"explanation":"Vas a escuchar a una profesora que te habla a vos y una conversación en clase. Fijate qué te pregunta, qué te pide y qué problema tiene cada uno.","examples":[{"target":"I don't understand.","base":"No entiendo."},{"target":"Can you speak slowly, please?","base":"¿Podés hablar más despacio, por favor?"}]},"takeaways":["Ahora podés entender cuándo alguien no entiende y qué pide para resolverlo."]}],"exercises":[{"id":"a1-u01-context-e01","lesson_id":"a1-u01-context","position":1,"type":"context_choice","skill":"reading","prompt_es":"Leé el texto y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u01-welcome-message","document":"message","setting":"Un mensaje en el chat de un curso nuevo.","lines":["Good morning, Tom!","My name is Ana. Nice to meet you.","How are you?"]},"question":"¿Quién escribe el mensaje?","options":["Ana","Tom","El profesor del curso"]},"answer":"Ana","accepted_answers":[],"explanation_es":"Dice «My name is Ana»: la que escribe es Ana, y le escribe a Tom.","difficulty":2,"recommended_seconds":60},{"id":"a1-u01-context-e02","lesson_id":"a1-u01-context","position":2,"type":"context_choice","skill":"reading","prompt_es":"Leé el texto y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u01-welcome-message","document":"message","setting":"Un mensaje en el chat de un curso nuevo.","lines":["Good morning, Tom!","My name is Ana. Nice to meet you.","How are you?"]},"question":"¿En qué momento del día escribe?","options":["A la tarde","A la mañana","A la noche"]},"answer":"A la mañana","accepted_answers":[],"explanation_es":"«Good morning» se usa a la mañana.","difficulty":2,"recommended_seconds":60},{"id":"a1-u01-context-e03","lesson_id":"a1-u01-context","position":3,"type":"context_choice","skill":"reading","prompt_es":"Leé el texto y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u01-welcome-message","document":"message","setting":"Un mensaje en el chat de un curso nuevo.","lines":["Good morning, Tom!","My name is Ana. Nice to meet you.","How are you?"]},"question":"¿Qué le pregunta Ana a Tom?","options":["Cómo está","Cómo se llama","Dónde vive"]},"answer":"Cómo está","accepted_answers":[],"explanation_es":"«How are you?» es «¿Cómo estás?».","difficulty":2,"recommended_seconds":60},{"id":"a1-u01-context-e04","lesson_id":"a1-u01-context","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u01-first-meeting","setting":"Dos personas se encuentran por primera vez.","speakers":[{"name":"Tom","voice":"a"},{"name":"Lucy","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Tom","text":"Good afternoon! My name is Tom."},{"speaker":"Lucy","text":"Hi, Tom. My name is Lucy. Nice to meet you."},{"speaker":"Tom","text":"Nice to meet you, Lucy. How are you?"},{"speaker":"Lucy","text":"Fine, thank you. And you?"}]},"question":"¿Qué están haciendo Tom y Lucy?","options":["Se despiden hasta mañana","Se presentan por primera vez","Se piden perdón"]},"answer":"Se presentan por primera vez","accepted_answers":[],"explanation_es":"Dicen sus nombres y «Nice to meet you»: se están conociendo.","difficulty":2,"recommended_seconds":75},{"id":"a1-u01-context-e05","lesson_id":"a1-u01-context","position":5,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u01-first-meeting","setting":"Dos personas se encuentran por primera vez.","speakers":[{"name":"Tom","voice":"a"},{"name":"Lucy","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Tom","text":"Good afternoon! My name is Tom."},{"speaker":"Lucy","text":"Hi, Tom. My name is Lucy. Nice to meet you."},{"speaker":"Tom","text":"Nice to meet you, Lucy. How are you?"},{"speaker":"Lucy","text":"Fine, thank you. And you?"}]},"question":"¿Cómo está Lucy?","options":["Bien","Mal","No responde"]},"answer":"Bien","accepted_answers":[],"explanation_es":"Lucy responde «Fine, thank you»: está bien.","difficulty":2,"recommended_seconds":75},{"id":"a1-u01-context-e06","lesson_id":"a1-u01-context","position":6,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u01-first-meeting","setting":"Dos personas se encuentran por primera vez.","speakers":[{"name":"Tom","voice":"a"},{"name":"Lucy","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Tom","text":"Good afternoon! My name is Tom."},{"speaker":"Lucy","text":"Hi, Tom. My name is Lucy. Nice to meet you."},{"speaker":"Tom","text":"Nice to meet you, Lucy. How are you?"},{"speaker":"Lucy","text":"Fine, thank you. And you?"}]},"question":"¿En qué momento del día se encuentran?","options":["A la tarde","A la mañana","A la noche"]},"answer":"A la tarde","accepted_answers":[],"explanation_es":"Tom saluda con «Good afternoon», que se usa a la tarde.","difficulty":2,"recommended_seconds":75},{"id":"a1-u02-context-e01","lesson_id":"a1-u02-context","position":1,"type":"context_choice","skill":"reading","prompt_es":"Leé el texto y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"reading","id":"en.stim.a1-u02-class-card","document":"description","setti