us":{"kind":"reading","id":"en.stim.a1-u03-player-cards","document":"notice","setting":"Las tarjetas de tres jugadores de un equipo de fútbol infantil.","title":"Team players","lines":["Lucas: number 7. From Argentina. 12 years old.","Emma: number 10. From England. 11 years old.","Pablo: number 3. From Spain. 12 years old."]},"question":"¿Qué tienen en común Lucas y Pablo?","options":["La edad","El país","El número"]},"answer":"La edad","accepted_answers":[],"explanation_es":"Los dos tienen 12 años, pero son de países distintos y tienen otro número.","difficulty":2,"recommended_seconds":60},{"id":"a1-u03-context-e04","lesson_id":"a1-u03-context","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u03-new-player","setting":"Un entrenador habla con un chico nuevo del equipo.","speakers":[{"name":"Ray","voice":"a"},{"name":"Max","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Ray","text":"Hello, Max! Where are you from?"},{"speaker":"Max","text":"I am from Mexico."},{"speaker":"Ray","text":"How old are you?"},{"speaker":"Max","text":"I am ten. My friend Leo is eleven."},{"speaker":"Ray","text":"OK, Max. Your number is eight."}]},"question":"¿Quién es mayor, Max o su amigo Leo?","options":["Max","Tienen la misma edad","Leo"]},"answer":"Leo","accepted_answers":[],"explanation_es":"Max dice «I am ten» y su amigo Leo tiene «eleven»: Leo es mayor.","difficulty":2,"recommended_seconds":75},{"id":"a1-u03-context-e05","lesson_id":"a1-u03-context","position":5,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u03-new-player","setting":"Un entrenador habla con un chico nuevo del equipo.","speakers":[{"name":"Ray","voice":"a"},{"name":"Max","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Ray","text":"Hello, Max! Where are you from?"},{"speaker":"Max","t