skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u12-teacher-to-you","setting":"En clase, la profesora te habla a vos.","speakers":[{"name":"Ms. Park","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Ms. Park","text":"Good morning! What is your name?"},{"speaker":"Ms. Park","text":"Do you speak Spanish?"},{"speaker":"Ms. Park","text":"Please repeat the word slowly."}]},"question":"¿Qué respuesta corresponde a su segunda pregunta?","options":["Yes, I do.","Yes, I am.","Yes, it is."]},"answer":"Yes, I do.","accepted_answers":[],"explanation_es":"A «Do you speak Spanish?» se responde con «do»: «Yes, I do» o «No, I don't».","difficulty":2,"recommended_seconds":75},{"id":"a1-u12-context-e03","lesson_id":"a1-u12-context","position":3,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u12-teacher-to-you","setting":"En clase, la profesora te habla a vos.","speakers":[{"name":"Ms. Park","voice":"b"}],"rate":0.85,"lines":[{"speaker":"Ms. Park","text":"Good morning! What is your name?"},{"speaker":"Ms. Park","text":"Do you speak Spanish?"},{"speaker":"Ms. Park","text":"Please repeat the word slowly."}]},"question":"¿Qué te pide que hagas al final?","options":["Que escribas la palabra","Que traduzcas la palabra al español","Que repitas la palabra despacio"]},"answer":"Que repitas la palabra despacio","accepted_answers":[],"explanation_es":"«Please repeat the word slowly».","difficulty":2,"recommended_seconds":75},{"id":"a1-u12-context-e04","lesson_id":"a1-u12-context","position":4,"type":"context_choice","skill":"listening","prompt_es":"Escuchá y respondé.","payload":{"type":"context_choice","stimulus":{"kind":"listening","id":"en.stim.a1-u12-in-class","setting":"Ben y su profesora conversan en clase.","speakers":[{"name":"Ben","voice":"a"},{"name":"Ms. Park","voice":"b"}],"rate":0.85,"